mapper.update:
UPDATE dashboard
   SET display_name = #{dashboard.displayName}, description = #{dashboard.description},
       default_zone_id = #{dashboard.defaultZoneId}, status = #{dashboard.status},
       version = #{dashboard.version}, updated_at = #{dashboard.updatedAt}
 WHERE id = #{dashboard.id}
   AND version = #{expectedVersion}

UPDATE dashboard
   SET version = #{newVersion}, updated_at = #{updatedAt}
 WHERE id = #{dashboardId}
   AND version = #{expectedVersion}
   AND status = 'ACTIVE'

UPDATE dashboard_widget
   SET meter_id = #{widget.meterId}, title = #{widget.title},
       visualization = #{widget.visualization}, value_field = #{widget.valueField},
       aggregation = #{widget.aggregation}, bucket_seconds = #{widget.bucketSeconds},
       layout = CAST(#{widget.layoutJson} AS jsonb), sort_order = #{widget.sortOrder},
       updated_at = #{widget.updatedAt}
 WHERE id = #{widget.id}
   AND dashboard_id = #{widget.dashboardId}

mapper.delete:
DELETE FROM dashboard_widget
 WHERE id = #{widgetId}
   AND dashboard_id = #{dashboardId}
